import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { db, storage } from '../../firebase';
import PermissionsMenu from '../Shared/PermissionsMenu';
import PagePermissionsPanel from '../Shared/PagePermissionsPanel';
import { usePermissions } from '../../hooks/usePermissions';
import {
  collection,
  query,
  where,
  getDocs,
  getDoc,
  addDoc,
  updateDoc,
  doc,
  orderBy,
  onSnapshot,
  arrayUnion,
  arrayRemove
} from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import Header from '../Layout/Header';
import SpreadsheetEditor from './SpreadsheetEditor';
import DocumentEditor from './DocumentEditor';
import AttendanceSheetEditor from './AttendanceSheetEditor';
import AttendanceSheetWizard from './AttendanceSheetWizard';
import GradeMappingEditor from './GradeMappingEditor';
import { subscribeClasses } from '../../services/firestore/classStudentRepository';
import { fileTrashAction } from '../../services/adminUserService';
import {
  FolderPlus,
  Upload,
  Trash2,
  FileText,
  Folder,
  FolderOpen,
  Download,
  Lock,
  X,
  Table2,
  FileEdit,
  Plus,
  Save,
  Search,
  Pin,
  ChevronDown,
  ChevronLeft,
  Maximize2,
  Minimize2,
  Share2,
  Pencil,
  Info,
  MoreVertical,
  Copy,
  History,
  Clock,
  ClipboardCheck,
  Printer,
  FileDown,
  RotateCcw,
} from 'lucide-react';
import { createNotifications } from '../../utils/notifications';
import '../Gantt/Gantt.css';
import './Files.css';

export default function FileManager() {
  const { userData, currentUser, selectedSchool, isPrincipal, isGlobalAdmin } = useAuth();
  const { permissions, schoolWidePermissions, permissionScopes } = usePermissions();
  const [showPermissionsPanel, setShowPermissionsPanel] = useState(false);
  const [searchParams, setSearchParams] = useSearchParams();
  const uid = currentUser?.uid;
  const [legacyFolders, setLegacyFolders] = useState([]);
  const [nestedFolders, setNestedFolders] = useState([]);
  const [legacyFiles, setLegacyFiles] = useState([]);
  const [nestedFiles, setNestedFiles] = useState([]);
  const [showNewFolder, setShowNewFolder] = useState(false);
  const [folderName, setFolderName] = useState('');
  const [folderVisibility, setFolderVisibility] = useState('all');
  const [uploading, setUploading] = useState(false);

  // In-app file editing
  const [editingFile, setEditingFile] = useState(null);
  const [showCreateMenu, setShowCreateMenu] = useState(false);
  const [newFileName, setNewFileName] = useState('');
  const [newFileType, setNewFileType] = useState(null);
  const [fileSaving, setFileSaving] = useState(false);
  const [fileSearch, setFileSearch] = useState('');
  const [permMenu, setPermMenu] = useState(null);
  const [expandedFolders, setExpandedFolders] = useState({});
  const [selectedFolder, setSelectedFolder] = useState(null);
  const [fullscreen, setFullscreen] = useState(false);
  const [createInFolder, setCreateInFolder] = useState(null);
  const [contextMenu, setContextMenu] = useState(null);
  const [renamingItem, setRenamingItem] = useState(null);
  const [renameValue, setRenameValue] = useState('');
  const [viewerContextMenu, setViewerContextMenu] = useState(null);
  const [folderPerms, setFolderPerms] = useState({});
  const [showHistory, setShowHistory] = useState(false);
  const [historyEntries, setHistoryEntries] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [attendanceClasses, setAttendanceClasses] = useState([]);
  const [showAttendanceWizard, setShowAttendanceWizard] = useState(false);
  const [attendanceInitialClassId, setAttendanceInitialClassId] = useState('');
  const [attendanceMessage, setAttendanceMessage] = useState('');
  const [showTrash, setShowTrash] = useState(false);
  const [trashBusyId, setTrashBusyId] = useState('');
  const autoSaveTimerRef = useRef(null);
  const lastSavedContentRef = useRef(null);
  const fileEditNotifSentRef = useRef(null); // track which file we already notified about

  const schoolId = selectedSchool || userData?.schoolId;
  const canManage = isPrincipal() || isGlobalAdmin();
  const canUploadFiles = permissions.files_upload;
  const attendanceSchoolWide = canManage
    || permissions.attendance_create
    || permissions.attendance_view
    || permissions.attendance_edit
    || permissions.attendance_manage_legend
    || permissions.attendance_manage_dates
    || permissions.attendance_block_days;
  const gradesSchoolWide = canManage
    || schoolWidePermissions['grades.view']
    || schoolWidePermissions['grades.edit']
    || schoolWidePermissions['gradebooks.manage'];
  const canCreateAttendance = attendanceSchoolWide
    || attendanceClasses.some(item => item.teacherId === uid);
  const permissionForClass = useCallback((key, classId) => (
    schoolWidePermissions[key] === true
    || (
      permissionScopes[key]?.type === 'classes'
      && permissionScopes[key].classIds.includes(classId)
    )
  ), [permissionScopes, schoolWidePermissions]);

  const attendanceClassForFile = useCallback((file) => (
    attendanceClasses.find(item => item.id === file.classId)
  ), [attendanceClasses]);

  const accessibleClassIds = useMemo(() => {
    const values = new Set(attendanceClasses.map(item => item.id));
    const scoped = userData?.classRolePermissionsBySchool?.[schoolId] || {};
    Object.values(scoped).forEach(classIds => (classIds || []).forEach(classId => values.add(classId)));
    return [...values];
  }, [attendanceClasses, schoolId, userData?.classRolePermissionsBySchool]);

  const userCanOpenFile = useCallback((file) => {
    if (file.fileType === 'attendance') {
      return canManage || attendanceSchoolWide || accessibleClassIds.includes(file.classId);
    }
    if (file.fileType === 'gradebook') {
      return canManage || gradesSchoolWide || accessibleClassIds.includes(file.classId);
    }
    return true;
  }, [accessibleClassIds, attendanceSchoolWide, canManage, gradesSchoolWide]);

  const userCanAccessFolder = useCallback((folder) => {
    if (canManage) return true;
    if (folder.visibility === 'class_restricted') return accessibleClassIds.includes(folder.classId);
    if (folder.visibility === 'principal_only') return false;
    // Check resource_permissions for this folder
    const perm = folderPerms[folder.id];
    if (perm && !perm.public) {
      // Folder has specific permissions set - check user and team access
      const uid = userData?.uid;
      const userTeamIds = userData?.teamIds || [];
      const isInViewers = perm.viewers?.includes(uid) || perm.editors?.includes(uid);
      const isInTeam = (perm.viewerTeams || []).some(t => userTeamIds.includes(t)) ||
                       (perm.editorTeams || []).some(t => userTeamIds.includes(t));
      return isInViewers || isInTeam;
    }
    // No specific permissions or public - use legacy checks
    if (folder.visibility === 'all') return true;
    if (folder.allowedUsers && folder.allowedUsers.includes(userData?.uid)) return true;
    return false;
  }, [accessibleClassIds, canManage, folderPerms, userData]);

  const accessibleFolders = useMemo(() => [...legacyFolders, ...nestedFolders]
    .filter(userCanAccessFolder), [legacyFolders, nestedFolders, userCanAccessFolder]);
  const accessibleFiles = useMemo(() => [...legacyFiles, ...nestedFiles].filter(userCanOpenFile), [legacyFiles, nestedFiles, userCanOpenFile]);
  const folders = useMemo(() => accessibleFolders.filter(item => !item.trashedAt), [accessibleFolders]);
  const files = useMemo(() => accessibleFiles.filter(item => !item.trashedAt), [accessibleFiles]);
  const trashedFolders = useMemo(() => accessibleFolders.filter(item => item.trashedAt), [accessibleFolders]);
  const trashedFiles = useMemo(() => accessibleFiles.filter(item => item.trashedAt), [accessibleFiles]);

  function userCanCreateFiles() {
    if (!canUploadFiles) return false;
    if (canManage) return true;
    const folder = folders.find(f => f.id === selectedFolder);
    if (!folder) return false;
    if (folder.allowCreate && folder.allowCreate.includes(userData?.uid)) return true;
    if (userData?.role === 'editor') return true;
    return false;
  }

  async function togglePinFile(fileItem, isPinned) {
    if (!uid || !schoolId) return;
    const fileRef = fileItem._dataMode === 'nested'
      ? doc(db, 'schools', schoolId, 'files', fileItem.id)
      : doc(db, `files_${schoolId}`, fileItem.id);
    await updateDoc(fileRef, {
      pinnedBy: isPinned ? arrayRemove(uid) : arrayUnion(uid)
    });
  }

  async function togglePinFolder(folder, isPinned) {
    if (!uid || !schoolId) return;
    const folderRef = folder._dataMode === 'nested'
      ? doc(db, 'schools', schoolId, 'folders', folder.id)
      : doc(db, `folders_${schoolId}`, folder.id);
    await updateDoc(folderRef, {
      pinnedBy: isPinned ? arrayRemove(uid) : arrayUnion(uid)
    });
  }

  // Load resource permissions for folders
  useEffect(() => {
    if (!schoolId) return;
    const q = query(collection(db, `folders_${schoolId}`));
    const unsub = onSnapshot(q, async (snap) => {
      const perms = {};
      await Promise.all(snap.docs.map(async (d) => {
        try {
          const permDoc = await getDoc(doc(db, 'resource_permissions', `folder_${d.id}`));
          if (permDoc.exists()) perms[d.id] = permDoc.data();
        } catch {}
      }));
      setFolderPerms(perms);
    });
    return unsub;
  }, [schoolId]);

  useEffect(() => {
    if (!schoolId) return;
    const q = query(collection(db, `folders_${schoolId}`), orderBy('name'));
    const unsub = onSnapshot(q, (snap) => {
      const allFolders = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setLegacyFolders(allFolders.map(folder => ({ ...folder, _dataMode: 'legacy' })));
    });
    return unsub;
  }, [schoolId]);

  useEffect(() => {
    if (!schoolId || (!canManage && !attendanceSchoolWide && !gradesSchoolWide && accessibleClassIds.length === 0)) {
      setNestedFolders([]);
      return undefined;
    }
    const base = collection(db, 'schools', schoolId, 'folders');
    const folderQuery = canManage || attendanceSchoolWide || gradesSchoolWide
      ? query(base, orderBy('name'))
      : query(base, where('classId', 'in', accessibleClassIds.slice(0, 30)));
    return onSnapshot(folderQuery, snapshot => {
      setNestedFolders(snapshot.docs.map(item => ({ id: item.id, ...item.data(), _dataMode: 'nested' })));
    }, () => setNestedFolders([]));
  }, [accessibleClassIds, attendanceSchoolWide, canManage, gradesSchoolWide, schoolId]);

  // Load all files for all folders
  useEffect(() => {
    if (!schoolId) return;
    const q = query(collection(db, `files_${schoolId}`), orderBy('createdAt', 'desc'));
    const unsub = onSnapshot(q, (snap) => {
      setLegacyFiles(snap.docs.map(d => ({ id: d.id, ...d.data(), _dataMode: 'legacy' })));
    });
    return unsub;
  }, [schoolId]);

  useEffect(() => {
    if (!schoolId || (!canManage && !attendanceSchoolWide && !gradesSchoolWide && accessibleClassIds.length === 0)) {
      setNestedFiles([]);
      return undefined;
    }
    const base = collection(db, 'schools', schoolId, 'files');
    const queries = canManage
      ? [['all', query(base, orderBy('createdAt', 'desc'))]]
      : [
          ...(attendanceSchoolWide ? [['attendance', query(base, where('fileType', '==', 'attendance'))]] : []),
          ...(gradesSchoolWide ? [['gradebook', query(base, where('fileType', '==', 'gradebook'))]] : []),
          ...(accessibleClassIds.length > 0 ? [['classes', query(base, where('classId', 'in', accessibleClassIds.slice(0, 30)))]] : []),
        ];
    const results = new Map();
    const publish = () => setNestedFiles([...new Map(
      [...results.values()].flat().map(item => [item.id, item]),
    ).values()]);
    const unsubscribers = queries.map(([key, filesQuery]) => onSnapshot(filesQuery, snapshot => {
      results.set(key, snapshot.docs.map(item => ({ id: item.id, ...item.data(), _dataMode: 'nested' })));
      publish();
    }, () => {
      results.set(key, []);
      publish();
    }));
    return () => unsubscribers.forEach(unsubscribe => unsubscribe());
  }, [accessibleClassIds, attendanceSchoolWide, canManage, gradesSchoolWide, schoolId]);

  useEffect(() => {
    if (!schoolId || !uid) return undefined;
    return subscribeClasses({
      db,
      schoolId,
      uid,
      canViewAll: attendanceSchoolWide || gradesSchoolWide,
      onData: items => setAttendanceClasses(items.filter(item => item.status !== 'archived')),
      onError: () => setAttendanceClasses([]),
    });
  }, [attendanceSchoolWide, gradesSchoolWide, schoolId, uid]);

  // Open file from URL param (e.g. /files?openFile=abc123)
  useEffect(() => {
    const openFileId = searchParams.get('openFile');
    if (openFileId && files.length > 0 && !editingFile) {
      const file = files.find(f => f.id === openFileId);
      if (file && ['spreadsheet', 'document', 'attendance', 'gradebook'].includes(file.fileType) && userCanOpenFile(file)) {
        setEditingFile(file);
        if (file.folderId) {
          setSelectedFolder(file.folderId);
          setExpandedFolders(prev => ({ ...prev, [file.folderId]: true }));
        }
      }
      // Clear the param so it doesn't re-trigger
      setSearchParams({}, { replace: true });
    }
  }, [searchParams, files, editingFile, setSearchParams, userCanOpenFile]);

  useEffect(() => {
    const requestedClassId = searchParams.get('createAttendance');
    if (!requestedClassId || !canCreateAttendance) return;
    const requestedFolderId = searchParams.get('folderId');
    if (requestedFolderId) {
      setCreateInFolder(requestedFolderId);
      setSelectedFolder(requestedFolderId);
      setExpandedFolders(previous => ({ ...previous, [requestedFolderId]: true }));
    }
    setAttendanceInitialClassId(requestedClassId);
    setShowAttendanceWizard(true);
    setSearchParams({}, { replace: true });
  }, [canCreateAttendance, searchParams, setSearchParams]);

  function openAttendanceWizard(folderId = selectedFolder, classId = '') {
    setCreateInFolder(folderId || null);
    setAttendanceInitialClassId(classId);
    setShowCreateMenu(false);
    setViewerContextMenu(null);
    setShowAttendanceWizard(true);
  }

  async function createFolder(e) {
    e.preventDefault();
    if (!folderName.trim() || !schoolId) return;
    try {
      await addDoc(collection(db, `folders_${schoolId}`), {
        name: folderName.trim(),
        visibility: folderVisibility,
        allowedUsers: [],
        allowCreate: [],
        createdBy: userData?.fullName || '',
        createdAt: new Date().toISOString()
      });
      setFolderName('');
      setShowNewFolder(false);
    } catch (err) {
      alert('שגיאה ביצירת תיקייה: ');
    }
  }

  async function handleUpload(e, folderId) {
    const file = e.target.files[0];
    if (!file || !folderId || !schoolId) return;
    setUploading(true);
    try {
      const storageRef = ref(storage, `schools/${schoolId}/${folderId}/${file.name}`);
      await uploadBytes(storageRef, file);
      const url = await getDownloadURL(storageRef);
      await addDoc(collection(db, `files_${schoolId}`), {
        name: file.name,
        url,
        size: file.size,
        type: file.type,
        fileType: 'upload',
        folderId: folderId,
        storagePath: `schools/${schoolId}/${folderId}/${file.name}`,
        uploadedBy: userData?.fullName || '',
        createdAt: new Date().toISOString()
      });
    } catch (err) {
      alert('שגיאה בהעלאת הקובץ');
    }
    setUploading(false);
    e.target.value = '';
  }

  async function createInAppFile(e) {
    e.preventDefault();
    const folderId = createInFolder || selectedFolder;
    if (!newFileName.trim() || !newFileType || !folderId || !schoolId) return;
    try {
      const initialContent = newFileType === 'spreadsheet'
        ? JSON.stringify({ columns: 5, rows: 10, cells: {}, headers: {}, columnWidths: {}, rowHeights: {} })
        : '<p></p>';

      const newDoc = await addDoc(collection(db, `files_${schoolId}`), {
        name: newFileName.trim(),
        fileType: newFileType,
        content: initialContent,
        folderId: folderId,
        size: 0,
        type: newFileType === 'spreadsheet' ? 'application/x-spreadsheet' : 'text/html',
        uploadedBy: userData?.fullName || '',
        createdAt: new Date().toISOString()
      });
      setNewFileName('');
      setNewFileType(null);
      setShowCreateMenu(false);
      setCreateInFolder(null);
      setEditingFile({ id: newDoc.id, name: newFileName.trim(), fileType: newFileType, content: initialContent });
    } catch (err) {
      alert('שגיאה ביצירת קובץ: ');
    }
  }

  const computeSpreadsheetChanges = useCallback((oldContent, newContent) => {
    try {
      const oldData = typeof oldContent === 'string' ? JSON.parse(oldContent) : oldContent;
      const newData = typeof newContent === 'string' ? JSON.parse(newContent) : newContent;
      if (!oldData || !newData) return [];
      const changes = [];
      const oldCells = oldData.cells || {};
      const newCells = newData.cells || {};
      const allRefs = new Set([...Object.keys(oldCells), ...Object.keys(newCells)]);
      for (const ref of allRefs) {
        const oldVal = oldCells[ref]?.value || '';
        const newVal = newCells[ref]?.value || '';
        const oldFormula = oldCells[ref]?.formula || '';
        const newFormula = newCells[ref]?.formula || '';
        if (oldVal !== newVal || oldFormula !== newFormula) {
          changes.push({ cell: ref, oldValue: oldFormula || oldVal, newValue: newFormula || newVal });
        }
      }
      return changes.slice(0, 50); // limit to 50 changes per save
    } catch { return []; }
  }, []);

  const saveFileContent = useCallback(async (content) => {
    if (!editingFile || !schoolId) return;
    setFileSaving(true);
    const prevContent = lastSavedContentRef.current;
    try {
      const now = new Date().toISOString();
      await updateDoc(doc(db, `files_${schoolId}`, editingFile.id), {
        content,
        lastModified: now,
        lastModifiedBy: userData?.fullName || ''
      });

      // Write edit history entry
      try {
        const historyEntry = {
          fileId: editingFile.id,
          fileName: editingFile.name,
          fileType: editingFile.fileType,
          userId: uid,
          userName: userData?.fullName || '',
          timestamp: now,
        };
        if (editingFile.fileType === 'spreadsheet') {
          historyEntry.changes = computeSpreadsheetChanges(prevContent, content);
        } else {
          historyEntry.summary = 'עריכת מסמך';
        }
        // Only write if there are actual changes
        if (editingFile.fileType !== 'spreadsheet' || historyEntry.changes.length > 0) {
          await addDoc(collection(db, `file_history_${schoolId}`), historyEntry);
        }
      } catch {}

      lastSavedContentRef.current = content;
      setEditingFile(prev => ({ ...prev, content }));
      // Notify team members about file edit (once per file session)
      if (fileEditNotifSentRef.current !== editingFile.id) {
        fileEditNotifSentRef.current = editingFile.id;
        const folderId = editingFile.folderId;
        const folder = folders.find(f => f.id === folderId);
        // Notify allowed users of the folder
        if (folder?.allowedUsers) {
          const otherIds = folder.allowedUsers.filter(id => id !== uid);
          if (otherIds.length > 0) {
            createNotifications(otherIds, {
              schoolId,
              title: `הקובץ "${editingFile.name}" נערך`,
              body: `${userData?.fullName || 'משתמש'} ערך/ה את הקובץ`,
              type: 'file',
              link: '/files'
            });
          }
        }
      }
    } catch (err) {
      alert('שגיאה בשמירה: ');
    }
    setFileSaving(false);
  }, [computeSpreadsheetChanges, editingFile, folders, schoolId, uid, userData?.fullName]);

  // Auto-save: debounce 1 second after last change
  const autoSave = useCallback((content) => {
    if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    autoSaveTimerRef.current = setTimeout(() => {
      if (content !== lastSavedContentRef.current) {
        saveFileContent(content);
      }
    }, 1000);
  }, [saveFileContent]);

  useEffect(() => {
    return () => {
      if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    };
  }, []);

  // Track initial content when opening a file
  useEffect(() => {
    if (editingFile) {
      lastSavedContentRef.current = editingFile.content;
    }
  }, [editingFile]);

  async function deleteFolder(folder) {
    if (!canManage && !permissions.files_delete && !permissions['files.delete']) return;
    if (!confirm(`להעביר את התיקייה "${folder.name}" ואת תוכנה לסל המחזור?`)) return;
    setTrashBusyId(`folder_${folder.id}`);
    try {
      await fileTrashAction({ schoolId, resourceType: 'folder', resourceId: folder.id, action: 'trash' });
      if (selectedFolder === folder.id) setSelectedFolder(null);
      setAttendanceMessage('התיקייה הועברה לסל המחזור.');
    } catch { alert('לא ניתן להעביר את התיקייה לסל המחזור.'); }
    finally { setTrashBusyId(''); }
  }

  async function deleteFile(fileItem) {
    if (!canManage && !permissions.files_delete && !permissions['files.delete']) return;
    if (!confirm(`להעביר את "${fileItem.name}" לסל המחזור?`)) return;
    setTrashBusyId(`file_${fileItem.id}`);
    try {
      await fileTrashAction({ schoolId, resourceType: 'file', resourceId: fileItem.id, action: 'trash' });
      if (editingFile?.id === fileItem.id) setEditingFile(null);
      setAttendanceMessage('הקובץ הועבר לסל המחזור.');
    } catch { alert('לא ניתן להעביר את הקובץ לסל המחזור.'); }
    finally { setTrashBusyId(''); }
  }

  async function restoreTrashItem(resourceType, item) {
    setTrashBusyId(`${resourceType}_${item.id}`);
    try {
      await fileTrashAction({ schoolId, resourceType, resourceId: item.id, action: 'restore' });
      setAttendanceMessage(`${resourceType === 'folder' ? 'התיקייה' : 'הקובץ'} שוחזרו בהצלחה.`);
    } catch { alert('לא ניתן לשחזר את הפריט.'); }
    finally { setTrashBusyId(''); }
  }

  async function permanentlyDeleteTrashItem(resourceType, item) {
    if (!confirm(`מחיקה זו סופית ותסיר את "${item.name}" לחלוטין ממסד הנתונים. האם להמשיך?`)) return;
    if (!confirm('אישור אחרון: לא ניתן יהיה לשחזר את הפריט לאחר המחיקה.')) return;
    setTrashBusyId(`${resourceType}_${item.id}`);
    try {
      await fileTrashAction({ schoolId, resourceType, resourceId: item.id, action: 'purge', confirmPermanent: true });
      setAttendanceMessage('הפריט נמחק לצמיתות.');
    } catch { alert('לא ניתן למחוק את הפריט לצמיתות.'); }
    finally { setTrashBusyId(''); }
  }

  async function duplicateFile(fileItem) {
    if (!schoolId || !canUploadFiles) return;
    try {
      const { id: _id, ...data } = fileItem;
      await addDoc(collection(db, `files_${schoolId}`), {
        ...data,
        name: (data.name || 'קובץ') + ' - עותק',
        createdAt: new Date().toISOString(),
        uploadedBy: userData?.fullName || '',
        pinnedBy: [],
      });
    } catch (err) {
      alert('שגיאה בשכפול: ');
    }
  }

  function exportFile(file) {
    if (!file) return;
    if (file.fileType === 'document') {
      // Export document as HTML → print/PDF
      const content = typeof file.content === 'string' ? file.content : '';
      const printWindow = window.open('', '_blank');
      printWindow.document.write(`
        <!DOCTYPE html>
        <html dir="rtl" lang="he">
        <head>
          <meta charset="UTF-8">
          <title>${file.name}</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 2cm; direction: rtl; }
            @media print { body { padding: 1cm; } }
          </style>
        </head>
        <body>${content}</body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => { printWindow.print(); }, 300);
    } else if (file.fileType === 'spreadsheet') {
      // Export spreadsheet as CSV
      try {
        const data = typeof file.content === 'string' ? JSON.parse(file.content) : file.content;
        const rows = data?.rows || data?.data || [];
        const csvRows = rows.map(row => {
          const cells = Array.isArray(row) ? row : (row.cells || []);
          return cells.map(cell => {
            const val = typeof cell === 'object' ? (cell?.text ?? cell?.v ?? '') : (cell ?? '');
            return `"${String(val).replace(/"/g, '""')}"`;
          }).join(',');
        });
        const csvContent = '﻿' + csvRows.join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `${file.name}.csv`;
        link.click();
        URL.revokeObjectURL(link.href);
      } catch {
        alert('לא ניתן לייצא את הגיליון');
      }
    } else if (file.url) {
      // Uploaded file — open download
      const link = document.createElement('a');
      link.href = file.url;
      link.download = file.name || 'קובץ';
      link.target = '_blank';
      link.click();
    }
  }

  function openFile(file) {
    if (['spreadsheet', 'document', 'attendance', 'gradebook'].includes(file.fileType)) {
      if (!userCanOpenFile(file)) {
        alert('אין הרשאה לצפות בקובץ הכיתתי הזה.');
        return;
      }
      // Flush pending autosave for current file before switching
      if (editingFile && editingFile.id !== file.id && autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current);
        autoSaveTimerRef.current = null;
        if (editingFile.content !== lastSavedContentRef.current) {
          saveFileContent(editingFile.content);
        }
      }
      setEditingFile(file);
      if (['attendance', 'gradebook'].includes(file.fileType)) setShowHistory(false);
      lastSavedContentRef.current = file.content;
      fileEditNotifSentRef.current = null;
      // Reload history if panel is open
      if (showHistory) loadHistory(file.id);
    } else if (file.url) {
      window.open(file.url, '_blank');
    }
  }

  async function loadHistory(fileId) {
    if (!schoolId || !fileId) return;
    setHistoryLoading(true);
    try {
      const q = query(
        collection(db, `file_history_${schoolId}`),
        where('fileId', '==', fileId),
        orderBy('timestamp', 'desc')
      );
      const snap = await getDocs(q);
      setHistoryEntries(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    } catch {
      setHistoryEntries([]);
    }
    setHistoryLoading(false);
  }

  function toggleHistory() {
    if (showHistory) {
      setShowHistory(false);
    } else {
      setShowHistory(true);
      if (editingFile) loadHistory(editingFile.id);
    }
  }

  function formatHistoryTime(ts) {
    if (!ts) return '';
    const d = new Date(ts);
    return d.toLocaleDateString('he-IL', { day: '2-digit', month: '2-digit', year: '2-digit' }) + ' ' +
      d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' });
  }

  function formatSize(bytes) {
    if (!bytes) return '—';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  function getFileIcon(file, size = 15) {
    if (file.fileType === 'spreadsheet') return <Table2 size={size} className="file-icon file-icon--sheet" />;
    if (file.fileType === 'document') return <FileEdit size={size} className="file-icon file-icon--doc" />;
    if (file.fileType === 'attendance') return <ClipboardCheck size={size} className="file-icon file-icon--attendance" />;
    if (file.fileType === 'gradebook') return <Table2 size={size} className="file-icon file-icon--sheet" />;
    return <FileText size={size} className="file-icon" />;
  }

  function toggleFolder(folderId) {
    setExpandedFolders(prev => ({ ...prev, [folderId]: !prev[folderId] }));
    setSelectedFolder(folderId);
  }

  function getFolderTooltip(folder) {
    const parts = [];
    if (folder.createdAt) {
      const d = new Date(folder.createdAt);
      parts.push(`נוצר: ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`);
    }
    if (folder.createdBy) parts.push(`יוצר: ${folder.createdBy}`);
    if (folder.visibility === 'principal_only') parts.push('הרשאה: מנהל בלבד');
    else if (folder.allowedUsers?.length) parts.push(`הרשאות: ${folder.allowedUsers.length} משתמשים`);
    else parts.push('הרשאה: כולם');
    return parts.join('\n');
  }

  function getFileTooltip(f) {
    const parts = [];
    if (f.createdAt) {
      const d = new Date(f.createdAt);
      parts.push(`נוצר: ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`);
    }
    if (f.uploadedBy) parts.push(`העלה: ${f.uploadedBy}`);
    if (f.lastModified) {
      const d = new Date(f.lastModified);
      parts.push(`עודכן: ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`);
    }
    if (f.lastModifiedBy) parts.push(`עודכן ע"י: ${f.lastModifiedBy}`);
    const folder = folders.find(fd => fd.id === f.folderId);
    if (folder) parts.push(`תיקייה: ${folder.name}`);
    return parts.join('\n');
  }

  function getFolderNameForFile(fileId) {
    const file = files.find(f => f.id === fileId);
    if (!file) return '';
    const folder = folders.find(f => f.id === file.folderId);
    return folder?.name || '';
  }

  // Screen-aware context menu positioning
  function getMenuPosition(x, y, menuWidth = 200, menuHeight = 200) {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    return {
      x: x + menuWidth > vw ? Math.max(0, x - menuWidth) : x,
      y: y + menuHeight > vh ? Math.max(0, y - menuHeight) : y
    };
  }

  function handleContextMenu(e, type, item) {
    e.preventDefault();
    e.stopPropagation();
    const pos = getMenuPosition(e.clientX, e.clientY);
    setContextMenu({ type, item, position: pos });
    setViewerContextMenu(null);
  }

  function handleViewerContextMenu(e) {
    e.preventDefault();
    if (editingFile) return; // no context menu when editing
    const pos = getMenuPosition(e.clientX, e.clientY, 180, 160);
    setViewerContextMenu({ position: pos });
    setContextMenu(null);
  }

  // Close context menus on click outside
  useEffect(() => {
    function handleClick() {
      setContextMenu(null);
      setViewerContextMenu(null);
    }
    document.addEventListener('click', handleClick);
    return () => document.removeEventListener('click', handleClick);
  }, []);

  async function renameItem() {
    if (!renamingItem || !renameValue.trim()) return;
    try {
      if (renamingItem.type === 'folder') {
        await updateDoc(doc(db, `folders_${schoolId}`, renamingItem.id), { name: renameValue.trim() });
      } else {
        await updateDoc(doc(db, `files_${schoolId}`, renamingItem.id), { name: renameValue.trim() });
      }
    } catch (err) {
      alert('שגיאה בשינוי שם: ');
    }
    setRenamingItem(null);
    setRenameValue('');
  }

  function startRename(type, item) {
    setRenamingItem({ type, id: item.id });
    setRenameValue(item.name);
    setContextMenu(null);
  }

  function getFileInfo(f) {
    const parts = [];
    parts.push(`שם: ${f.name}`);
    if (f.createdAt) {
      const d = new Date(f.createdAt);
      parts.push(`נוצר: ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`);
    }
    if (f.uploadedBy) parts.push(`יוצר: ${f.uploadedBy}`);
    if (f.lastModified) {
      const d = new Date(f.lastModified);
      parts.push(`עודכן: ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`);
    }
    if (f.lastModifiedBy) parts.push(`עודכן ע"י: ${f.lastModifiedBy}`);
    if (f.fileType) parts.push(`סוג: ${f.fileType === 'spreadsheet' ? 'גיליון' : f.fileType === 'document' ? 'מסמך' : f.fileType === 'attendance' ? 'גיליון נוכחות' : f.fileType === 'gradebook' ? 'מיפוי ציונים' : 'קובץ'}`);
    if (f.size) parts.push(`גודל: ${formatSize(f.size)}`);
    alert(parts.join('\n'));
  }

  // Sort folders: pinned first, then alphabetical
  const sortedFolders = [...folders]
    .filter(f => !fileSearch.trim() || f.name.toLowerCase().includes(fileSearch.toLowerCase()) ||
      files.some(file => file.folderId === f.id && file.name.toLowerCase().includes(fileSearch.toLowerCase())))
    .sort((a, b) => {
      const aPin = a.pinnedBy?.includes(uid) ? 0 : 1;
      const bPin = b.pinnedBy?.includes(uid) ? 0 : 1;
      if (aPin !== bPin) return aPin - bPin;
      return (a.name || '').localeCompare(b.name || '');
    });

  const pinnedFolders = sortedFolders.filter(f => f.pinnedBy?.includes(uid));
  const unpinnedFolders = sortedFolders.filter(f => !f.pinnedBy?.includes(uid));

  function getFilesForFolder(folderId) {
    return files
      .filter(f => f.folderId === folderId)
      .filter(f => f.status !== 'archived')
      .filter(userCanOpenFile)
      .filter(f => !fileSearch.trim() || f.name.toLowerCase().includes(fileSearch.toLowerCase()))
      .sort((a, b) => {
        const aPin = a.pinnedBy?.includes(uid) ? 0 : 1;
        const bPin = b.pinnedBy?.includes(uid) ? 0 : 1;
        return aPin - bPin;
      });
  }

  // Get pinned files across all folders
  const pinnedFiles = files.filter(f => f.pinnedBy?.includes(uid))
    .filter(f => f.status !== 'archived')
    .filter(userCanOpenFile)
    .filter(f => !fileSearch.trim() || f.name.toLowerCase().includes(fileSearch.toLowerCase()));

  function renderFolderTree(folderList) {
    return folderList.map(folder => {
      const isExpanded = expandedFolders[folder.id];
      const folderFiles = getFilesForFolder(folder.id);
      const isPinnedFolder = folder.pinnedBy?.includes(uid);
      const isSelected = selectedFolder === folder.id;

      return (
        <div key={folder.id} className="tree-folder">
          <div
            className={`tree-folder-item ${isSelected ? 'tree-folder-item--active' : ''}`}
            onClick={() => toggleFolder(folder.id)}
            title={getFolderTooltip(folder)}
            onContextMenu={e => handleContextMenu(e, 'folder', folder)}
          >
            <span className="tree-chevron">
              {isExpanded ? <ChevronDown size={12} /> : <ChevronLeft size={12} />}
            </span>
            {isExpanded ? <FolderOpen size={15} /> : <Folder size={15} />}
            {renamingItem?.type === 'folder' && renamingItem.id === folder.id ? (
              <form className="rename-form-inline" onSubmit={e => { e.preventDefault(); renameItem(); }} onClick={e => e.stopPropagation()}>
                <input value={renameValue} onChange={e => setRenameValue(e.target.value)} autoFocus onBlur={renameItem} />
              </form>
            ) : (
              <span className="tree-folder-name">{folder.name}</span>
            )}
            {folder.visibility === 'principal_only' && <Lock size={10} className="folder-lock" />}
            <span className="tree-folder-count">{folderFiles.length}</span>
            <div className="tree-item-actions" onClick={e => e.stopPropagation()}>
              <button
                className={`tree-pin-btn ${isPinnedFolder ? 'tree-pin-btn--active' : ''}`}
                title={isPinnedFolder ? 'הסר נעיצה' : 'נעץ תיקייה'}
                onClick={() => togglePinFolder(folder, isPinnedFolder)}
              >
                <Pin size={11} style={isPinnedFolder ? { color: '#870335' } : undefined} />
              </button>
              {canManage && (
                <button
                  className="tree-delete-btn"
                  onClick={() => deleteFolder(folder)}
                  disabled={trashBusyId === `folder_${folder.id}`}
                  title="העברה לסל המחזור"
                >
                  <Trash2 size={11} />
                </button>
              )}
            </div>
          </div>

          {isExpanded && (
            <div className="tree-folder-children">
              {folderFiles.map(f => {
                const isPinned = f.pinnedBy?.includes(uid);
                return (
                  <div
                    key={f.id}
                    className={`tree-file-item ${editingFile?.id === f.id ? 'tree-file-item--active' : ''} ${isPinned ? 'tree-file-item--pinned' : ''}`}
                    onClick={() => openFile(f)}
                    title={getFileTooltip(f)}
                    onContextMenu={e => handleContextMenu(e, 'file', f)}
                  >
                    {getFileIcon(f, 13)}
                    {renamingItem?.type === 'file' && renamingItem.id === f.id ? (
                      <form className="rename-form-inline" onSubmit={e => { e.preventDefault(); renameItem(); }} onClick={e => e.stopPropagation()}>
                        <input value={renameValue} onChange={e => setRenameValue(e.target.value)} autoFocus onBlur={renameItem} />
                      </form>
                    ) : (
                      <span className="tree-file-name">{f.name}</span>
                    )}
                    <div className="tree-item-actions" onClick={e => e.stopPropagation()}>
                      {f.fileType !== 'gradebook' && (
                        <button
                          className={`tree-pin-btn ${isPinned ? 'tree-pin-btn--active' : ''}`}
                          title={isPinned ? 'הסר נעיצה' : 'נעץ'}
                          onClick={() => togglePinFile(f, isPinned)}
                        >
                          <Pin size={10} style={isPinned ? { color: '#870335' } : undefined} />
                        </button>
                      )}
                      {f.url && (
                        <a href={f.url} target="_blank" rel="noopener noreferrer" className="tree-action-btn" title="הורדה">
                          <Download size={10} />
                        </a>
                      )}
                      {canManage && (
                        <button className="tree-delete-btn" onClick={() => deleteFile(f)} disabled={trashBusyId === `file_${f.id}`} title="העברה לסל המחזור">
                          <Trash2 size={10} />
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
              {folderFiles.length === 0 && (
                <div className="tree-empty">ריק</div>
              )}
            </div>
          )}
        </div>
      );
    });
  }

  return (
    <div className="page">
      <Header title="קבצים ותיקיות" onPermissions={() => setShowPermissionsPanel(true)} />
      {attendanceMessage && (
        <div className="attendance-feedback attendance-feedback--success" role="status">
          {attendanceMessage}
        </div>
      )}
      {showPermissionsPanel && <PagePermissionsPanel feature="files" onClose={() => setShowPermissionsPanel(false)} />}
      <div className="page-content">
        <div className={`files-layout ${fullscreen ? 'files-layout--fullscreen' : ''}`}>
          {/* Right panel - File tree */}
          <div className="files-tree-panel">
            <div className="tree-panel-header">
              <h3>תיקיות וקבצים</h3>
              <div className="tree-panel-actions">
                {canManage && <button className="icon-btn" onClick={() => setShowTrash(true)} title="סל המחזור" aria-label="פתיחת סל המחזור"><Trash2 size={15} /></button>}
                {selectedFolder && userCanCreateFiles() && (
                  <>
                    <button className="icon-btn" onClick={() => { setNewFileType('spreadsheet'); setCreateInFolder(selectedFolder); }} title="גיליון חדש">
                      <Table2 size={15} />
                    </button>
                    <button className="icon-btn" onClick={() => { setNewFileType('document'); setCreateInFolder(selectedFolder); }} title="מסמך חדש">
                      <FileEdit size={15} />
                    </button>
                  </>
                )}
                {selectedFolder && canCreateAttendance && (
                  <button className="icon-btn" onClick={() => openAttendanceWizard(selectedFolder)} title="גיליון נוכחות חדש">
                    <ClipboardCheck size={15} />
                  </button>
                )}
                {canManage && (
                  <button className="icon-btn" onClick={() => setShowNewFolder(true)} title="תיקייה חדשה">
                    <FolderPlus size={15} />
                  </button>
                )}
              </div>
            </div>

            {showNewFolder && (
              <form onSubmit={createFolder} className="new-folder-form">
                <input
                  value={folderName}
                  onChange={e => setFolderName(e.target.value)}
                  placeholder="שם התיקייה"
                  autoFocus
                />
                <select value={folderVisibility} onChange={e => setFolderVisibility(e.target.value)}>
                  <option value="all">כולם</option>
                  <option value="principal_only">מנהל בלבד</option>
                </select>
                <div className="form-actions">
                  <button type="submit" className="btn btn-primary btn-sm">צור</button>
                  <button type="button" className="btn btn-secondary btn-sm" onClick={() => setShowNewFolder(false)}>ביטול</button>
                </div>
              </form>
            )}

            <div style={{ padding: '0.35rem 0.5rem 0' }}>
              <div className="search-bar" style={{ minWidth: 'auto' }}>
                <Search size={12} />
                <input
                  value={fileSearch}
                  onChange={e => setFileSearch(e.target.value)}
                  placeholder="חיפוש..."
                  style={{ fontSize: '0.75rem' }}
                />
              </div>
            </div>

            <div className="tree-list">
              {/* Pinned section */}
              {(pinnedFolders.length > 0 || pinnedFiles.length > 0) && (
                <>
                  <div className="tree-section-header">
                    <Pin size={11} />
                    <span>נעוצים</span>
                  </div>
                  {renderFolderTree(pinnedFolders)}
                  {pinnedFiles.filter(f => !pinnedFolders.some(pf => pf.id === f.folderId)).map(f => {
                    const folderName = getFolderNameForFile(f.id);
                    return (
                      <div
                        key={`pinned-${f.id}`}
                        className={`tree-file-item tree-file-item--pinned-standalone ${editingFile?.id === f.id ? 'tree-file-item--active' : ''}`}
                        onClick={() => openFile(f)}
                        title={getFileTooltip(f)}
                      >
                        {getFileIcon(f, 13)}
                        <span className="tree-file-name">
                          {f.name}
                          {folderName && <span className="tree-file-folder-tag">{folderName}</span>}
                        </span>
                        <div className="tree-item-actions" onClick={e => e.stopPropagation()}>
                          <button
                            className="tree-pin-btn tree-pin-btn--active"
                            title="הסר נעיצה"
                            onClick={() => togglePinFile(f, true)}
                          >
                            <Pin size={10} style={{ color: '#870335' }} />
                          </button>
                        </div>
                      </div>
                    );
                  })}
                  <div className="tree-section-divider" />
                </>
              )}

              {/* All folders */}
              {unpinnedFolders.length > 0 && (pinnedFolders.length > 0 || pinnedFiles.length > 0) && (
                <div className="tree-section-header">
                  <Folder size={11} />
                  <span>כל התיקיות</span>
                </div>
              )}
              {renderFolderTree(unpinnedFolders)}

              {sortedFolders.length === 0 && (
                <div className="tree-empty-state">
                  <Folder size={24} className="empty-icon" />
                  <p>אין תיקיות</p>
                </div>
              )}
            </div>
          </div>

          {/* Left panel - File viewer */}
          <div className="files-viewer-panel">
            {editingFile ? (
              <div className="file-viewer-content">
                <div className="file-editor-header">
                  <button className="btn btn-secondary btn-sm" onClick={() => { setEditingFile(null); setFullscreen(false); }}>
                    <X size={14} />
                    סגור
                  </button>
                  <span className="file-editor-name">
                    {editingFile.fileType === 'spreadsheet'
                      ? <Table2 size={16} />
                      : editingFile.fileType === 'gradebook'
                        ? <Table2 size={16} />
                      : editingFile.fileType === 'attendance'
                        ? <ClipboardCheck size={16} />
                        : <FileEdit size={16} />}
                    {editingFile.name}
                  </span>
                  <div className="file-editor-actions">
                    {!['spreadsheet', 'attendance', 'gradebook'].includes(editingFile.fileType) && (
                      <button
                        className="icon-btn"
                        onClick={() => setFullscreen(!fullscreen)}
                        title={fullscreen ? 'יציאה ממסך מלא' : 'מסך מלא'}
                      >
                        {fullscreen ? <Minimize2 size={15} /> : <Maximize2 size={15} />}
                      </button>
                    )}
                    {!!canUploadFiles && !['attendance', 'gradebook'].includes(editingFile.fileType) && (
                      <>
                        <span className="autosave-status">
                          <span className={`autosave-dot-inline ${fileSaving ? 'autosave-dot-inline--saving' : ''}`} />
                          {fileSaving ? 'שומר...' : 'שמירה אוטומטית'}
                        </span>
                        <button
                          className="btn btn-primary btn-sm"
                          onClick={() => saveFileContent(editingFile.content)}
                          disabled={fileSaving}
                        >
                          <Save size={14} />
                          שמירה
                        </button>
                      </>
                    )}
                    {!canUploadFiles && !['attendance', 'gradebook'].includes(editingFile.fileType) && <span style={{ fontSize: '0.78rem', color: '#9b8790' }}>צפייה בלבד</span>}
                    {!['attendance', 'gradebook'].includes(editingFile.fileType) && (
                      <>
                        <button
                          className="icon-btn"
                          onClick={() => exportFile(editingFile)}
                          title={editingFile.fileType === 'document' ? 'הדפסה / ייצוא PDF' : 'ייצוא CSV'}
                        >
                          {editingFile.fileType === 'document' ? <Printer size={15} /> : <FileDown size={15} />}
                        </button>
                        <button
                          className={`icon-btn ${showHistory ? 'icon-btn--active' : ''}`}
                          onClick={toggleHistory}
                          title="היסטוריית עריכה"
                        >
                          <History size={15} />
                        </button>
                      </>
                    )}
                  </div>
                </div>
                <div className="file-editor-body-wrap">
                <div className="file-editor-body">
                  {editingFile.fileType === 'attendance' ? (
                    <AttendanceSheetEditor
                      key={editingFile.id}
                      file={editingFile}
                      schoolId={schoolId}
                      actor={{ uid, fullName: userData?.fullName || '' }}
                      permissions={permissions}
                      canManage={canManage}
                      classItem={attendanceClassForFile(editingFile)}
                    />
                  ) : editingFile.fileType === 'gradebook' ? (
                    <GradeMappingEditor
                      key={editingFile.id}
                      file={editingFile}
                      schoolId={schoolId}
                      actor={{ uid, fullName: userData?.fullName || '' }}
                      canEditScores={canManage || permissionForClass('grades.edit', editingFile.classId) || [attendanceClassForFile(editingFile)?.teacherId, ...(attendanceClassForFile(editingFile)?.staffIds || [])].includes(uid)}
                      canManageConfig={canManage || permissionForClass('gradebooks.manage', editingFile.classId) || attendanceClassForFile(editingFile)?.teacherId === uid}
                    />
                  ) : editingFile.fileType === 'spreadsheet' ? (
                    <SpreadsheetEditor
                      key={editingFile.id}
                      data={typeof editingFile.content === 'string' ? JSON.parse(editingFile.content) : editingFile.content}
                      onChange={!canUploadFiles ? undefined : (newData) => {
                        const json = JSON.stringify(newData);
                        setEditingFile(prev => ({ ...prev, content: json }));
                        autoSave(json);
                      }}
                      onToggleFullscreen={() => setFullscreen(!fullscreen)}
                      isFullscreen={fullscreen}
                      readOnly={!canUploadFiles}
                    />
                  ) : (
                    <DocumentEditor
                      key={editingFile.id}
                      content={editingFile.content || ''}
                      onChange={!canUploadFiles ? undefined : (newContent) => {
                        setEditingFile(prev => ({ ...prev, content: newContent }));
                        autoSave(newContent);
                      }}
                      readOnly={!canUploadFiles}
                    />
                  )}
                </div>
                {/* Edit History Panel */}
                {showHistory && !['attendance', 'gradebook'].includes(editingFile.fileType) && (
                  <div className="file-history-panel">
                    <div className="file-history-header">
                      <History size={14} />
                      <span>היסטוריית עריכה</span>
                      <button className="icon-btn" onClick={() => setShowHistory(false)} style={{ marginRight: 'auto' }}>
                        <X size={14} />
                      </button>
                    </div>
                    <div className="file-history-list">
                      {historyLoading ? (
                        <div className="file-history-empty">טוען...</div>
                      ) : historyEntries.length === 0 ? (
                        <div className="file-history-empty">אין היסטוריית עריכה</div>
                      ) : historyEntries.map(entry => (
                        <div key={entry.id} className="file-history-entry">
                          <div className="file-history-entry-header">
                            <span className="file-history-user">{entry.userName || 'משתמש'}</span>
                            <span className="file-history-time">
                              <Clock size={11} />
                              {formatHistoryTime(entry.timestamp)}
                            </span>
                          </div>
                          {entry.fileType === 'spreadsheet' && entry.changes?.length > 0 ? (
                            <div className="file-history-changes">
                              {entry.changes.map((ch, i) => (
                                <div key={i} className="file-history-change">
                                  <span className="file-history-cell">{ch.cell}</span>
                                  {ch.oldValue ? (
                                    <>
                                      <span className="file-history-old">{ch.oldValue}</span>
                                      <span className="file-history-arrow">←</span>
                                      <span className="file-history-new">{ch.newValue}</span>
                                    </>
                                  ) : (
                                    <span className="file-history-new">{ch.newValue}</span>
                                  )}
                                </div>
                              ))}
                            </div>
                          ) : (
                            <div className="file-history-summary">{entry.summary || 'עריכה'}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                </div>
              </div>
            ) : selectedFolder ? (
              <div className="file-viewer-content">
                <div className="viewer-header">
                  <div className="viewer-folder-info">
                    <FolderOpen size={18} />
                    <h3>{folders.find(f => f.id === selectedFolder)?.name || 'תיקייה'}</h3>
                  </div>
                  <div className="viewer-header-actions">
                    {(userCanCreateFiles() || canCreateAttendance) && (
                      <div className="create-file-wrap">
                        <button
                          className="btn btn-primary btn-sm"
                          onClick={() => { setShowCreateMenu(!showCreateMenu); setCreateInFolder(selectedFolder); }}
                        >
                          <Plus size={14} />
                          קובץ חדש
                        </button>
                        {showCreateMenu && (
                          <div className="create-file-menu">
                            {userCanCreateFiles() && (
                              <>
                                <button onClick={() => { setNewFileType('spreadsheet'); setShowCreateMenu(false); }}>
                                  <Table2 size={16} />
                                  גיליון אלקטרוני
                                </button>
                                <button onClick={() => { setNewFileType('document'); setShowCreateMenu(false); }}>
                                  <FileEdit size={16} />
                                  מסמך טקסט
                                </button>
                              </>
                            )}
                            {canCreateAttendance && (
                              <button onClick={() => openAttendanceWizard(selectedFolder)}>
                                <ClipboardCheck size={16} />
                                גיליון נוכחות
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                    {!!canUploadFiles && (
                      <label className="upload-btn">
                        <Upload size={14} />
                        {uploading ? 'מעלה...' : 'העלאת קובץ'}
                        <input type="file" hidden onChange={e => handleUpload(e, selectedFolder)} disabled={uploading} />
                      </label>
                    )}
                  </div>
                </div>

                {newFileType && (
                  <form onSubmit={createInAppFile} className="new-file-form">
                    <div className="new-file-type-badge">
                      {newFileType === 'spreadsheet' ? <Table2 size={14} /> : <FileEdit size={14} />}
                      {newFileType === 'spreadsheet' ? 'גיליון חדש' : 'מסמך חדש'}
                    </div>
                    <input
                      value={newFileName}
                      onChange={e => setNewFileName(e.target.value)}
                      placeholder="שם הקובץ"
                      autoFocus
                      required
                    />
                    <div className="form-actions">
                      <button type="submit" className="btn btn-primary btn-sm">צור</button>
                      <button type="button" className="btn btn-secondary btn-sm" onClick={() => setNewFileType(null)}>ביטול</button>
                    </div>
