import { useState, useEffect, useRef } from 'react';
import { db } from '../../firebase';
import {
  collection, query, where, getDocs
} from 'firebase/firestore';
import { updateStaffUser } from '../../services/adminUserService';
import { Shield, X, Check, Users, Save } from 'lucide-react';

// Maps nav path → Firestore permission key
export const PATH_TO_PERMISSION = {
  '/calendar':    'calendar_view',
  '/categories':  'categories_view',
  '/staff':       'staff_view',
  '/tasks':       'tasks_view',
  '/files':       'files_view',
  '/teams':       'teams_view',
  '/students':    'students_view',
  '/contacts':    'contacts.view',
  '/holidays':    'holidays_view',
  '/messages':    'messages_send',
  '/settings':    'settings_edit',
};

// Default view permission for each key (viewer defaults = all view = true)
function defaultAllowed(permission) {
  return !['students_view', 'contacts.view'].includes(permission);
}

export default function NavPermissionsPanel({ item, anchor, schoolId, onClose }) {
  const panelRef = useRef(null);
  const [staff, setStaff] = useState([]);
  const [permissions, setPermissions] = useState({}); // uid → bool
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const permKey = PATH_TO_PERMISSION[item.path];

  // Position panel near right-click anchor, keeping it in viewport
  const [pos, setPos] = useState({ top: anchor.y, right: window.innerWidth - anchor.x });
  useEffect(() => {
    if (!panelRef.current) return;
    const { height, width } = panelRef.current.getBoundingClientRect();
    let top = anchor.y;
    let left = anchor.x;
    if (top + height > window.innerHeight - 12) top = window.innerHeight - height - 12;
    if (left + width > window.innerWidth - 12) left = window.innerWidth - width - 12;
    if (top < 8) top = 8;
    if (left < 8) left = 8;
    setPos({ top, left });
  }, [anchor, loading]);

  // Load staff and their current permissions
  useEffect(() => {
    if (!schoolId || !permKey) { setLoading(false); return; }
    async function load() {
      setLoading(true);
      try {
        const results = [];
        const seen = new Set();
        const q1 = query(collection(db, 'users'), where('schoolIds', 'array-contains', schoolId));
        const snap1 = await getDocs(q1);
        snap1.docs.forEach(d => {
          if (!seen.has(d.id)) { seen.add(d.id); results.push({ id: d.id, ...d.data() }); }
        });
        const q2 = query(collection(db, 'users'), where('schoolId', '==', schoolId));
        const snap2 = await getDocs(q2);
        snap2.docs.forEach(d => {
          if (!seen.has(d.id)) { seen.add(d.id); results.push({ id: d.id, ...d.data() }); }
        });

        // Filter out global admins (they always have access)
        const filteredStaff = results.filter(u => u.role !== 'global_admin');
        setStaff(filteredStaff);

        // Build initial permission map
        const pmap = {};
        filteredStaff.forEach(u => {
          const perms = u.permissions || {};
          // principal/editor always allowed; for viewer check explicit perm or default
          if (u.role === 'principal' || u.role === 'editor') {
            pmap[u.id] = true;
          } else {
            pmap[u.id] = permKey in perms ? !!perms[permKey] : defaultAllowed(permKey);
          }
        });
        setPermissions(pmap);
      } catch (err) {
        console.error('Error loading staff for nav permissions:');
      }
      setLoading(false);
    }
    load();
  }, [schoolId, permKey]);

  // Close on outside click
  useEffect(() => {
    function handleClick(e) {
      if (panelRef.current && !panelRef.current.contains(e.target)) onClose();
    }
    function handleKey(e) { if (e.key === 'Escape') onClose(); }
    document.addEventListener('mousedown', handleClick);
    document.addEventListener('keydown', handleKey);
    return () => {
      document.removeEventListener('mousedown', handleClick);
      document.removeEventListener('keydown', handleKey);
    };
  }, [onClose]);

  function toggle(uid) {
    const user = staff.find(u => u.id === uid);
    if (!user) return;
    // Principals and editors always have access — don't allow toggling for now
    if (user.role === 'principal') return;
    setPermissions(prev => ({ ...prev, [uid]: !prev[uid] }));
    setSaved(false);
  }

  async function save() {
    if (!permKey) return;
    setSaving(true);
    try {
      const updates = staff
        .filter(u => u.role !== 'principal')
        .map(u => {
          const currentPerms = u.permissions || {};
          return updateStaffUser({
            userId: u.id,
            schoolId,
            permissions: { ...currentPerms, [permKey]: !!permissions[u.id] },
          });
        });
      await Promise.all(updates);
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    } catch (err) {
      alert('שגיאה בשמירה: ');
    }
    setSaving(false);
  }

  if (!permKey) return null;

  const allowedCount = Object.values(permissions).filter(Boolean).length;

  return (
    <div
      ref={panelRef}
      className="nav-perm-panel"
      style={{ position: 'fixed', top: pos.top, left: pos.left, zIndex: 9999 }}
      onClick={e => e.stopPropagation()}
    >
      <div className="nav-perm-header">
        <Shield size={14} />
        <span>הרשאות גישה — {item.label}</span>
        <button className="nav-perm-close" onClick={onClose}><X size={14} /></button>
      </div>

      <div className="nav-perm-summary">
        <Users size={12} />
        <span>{allowedCount} מתוך {staff.length} בעלי גישה</span>
      </div>

      {loading ? (
        <div className="nav-perm-loading">טוען...</div>
      ) : (
        <div className="nav-perm-list">
          {staff.length === 0 && (
            <div className="nav-perm-empty">אין משתמשים בבית ספר זה</div>
          )}
          {staff.map(user => {
            const allowed = !!permissions[user.id];
            const isPrincipal = user.role === 'principal';
            return (
              <div
                key={user.id}
                className={`nav-perm-item ${allowed ? 'nav-perm-item--allowed' : 'nav-perm-item--blocked'} ${isPrincipal ? 'nav-perm-item--fixed' : ''}`}
                onClick={() => !isPrincipal && toggle(user.id)}
                title={isPrincipal ? 'מנהל מוסד — תמיד בעל גישה' : (allowed ? 'לחץ לחסימה' : 'לחץ לאישור גישה')}
              >
                <div className={`nav-perm-check ${allowed ? 'nav-perm-check--on' : ''}`}>
                  {allowed && <Check size={10} />}
                </div>
                <div className="nav-perm-user-info">
                  <span className="nav-perm-avatar">{user.fullName?.charAt(0) || '?'}</span>
                  <div>
                    <span className="nav-perm-name">{user.fullName || user.email}</span>
                    <span className="nav-perm-role">{user.jobTitle || user.role}</span>
                  </div>
                </div>
                {isPrincipal && <span className="nav-perm-locked">קבוע</span>}
              </div>
            );
          })}
        </div>
      )}

      <div className="nav-perm-footer">
        <button
          className="btn btn-primary btn-sm"
          onClick={save}
          disabled={saving}
          style={{ width: '100%', justifyContent: 'center' }}
        >
          <Save size={13} />
          {saving ? 'שומר...' : saved ? '✓ נשמר' : 'שמירת הרשאות'}
        </button>
        <p className="nav-perm-hint">השינויים יכנסו לתוקף בכניסה הבאה של המשתמש</p>
      </div>
    </div>
  );
}

src/components/Shared/PagePermissionsPan:
import { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { db, isAppCheckConfigured } from '../../firebase';
import {
  collection, getDocs, query, where
} from 'firebase/firestore';
import { callableReason, updateStaffUser } from '../../services/adminUserService';
import { Shield, X, Eye, Edit3, ChevronDown, ChevronUp, Users, Check } from 'lucide-react';

const FEATURE_LABELS = {
  calendar:    { label: 'לוח שנה',       view: 'calendar_view',    edit: 'calendar_edit', viewAlias: 'calendar.view', editAlias: 'calendar.edit' },
  categories:  { label: 'קטגוריות',      view: 'categories_view',  edit: 'categories_edit' },
  staff:       { label: 'סגל וקהילה',    view: 'staff_view',       edit: 'staff_edit' },
  tasks:       { label: 'משימות',         view: 'tasks_view',       edit: 'tasks_edit' },
  files:       { label: 'קבצים',          view: 'files_view',       edit: 'files_upload' },
  teams:       { label: 'צוותים',         view: 'teams_view',       edit: 'teams_edit' },
  students:    { label: 'כיתות ותלמידים', view: 'students_view',    edit: 'students_update' },
  messages:    { label: 'הודעות',         view: null,               edit: 'messages_send' },
  holidays:    { label: 'חגים וחופשות',  view: 'holidays_view',    edit: 'holidays_edit' },
  contacts:    { label: 'אנשי קשר',       view: 'contacts.view',    edit: 'contacts.edit', editExtra: ['contacts.create', 'contacts.archive'] },
};

const ROLE_LABELS = {
  global_admin: 'מנהל על',
  principal: 'מנהל מוסד',
  editor: 'עורך',
  viewer: 'צופה',
};

export default function PagePermissionsPanel({ feature, onClose }) {
  const { userData, selectedSchool, isGlobalAdmin, isPrincipal } = useAuth();
  const [staff, setStaff] = useState([]);
  const [saving, setSaving] = useState(null);
  const [saved, setSaved] = useState(null);
  const [panelError, setPanelError] = useState('');
  const [search, setSearch] = useState('');
  const panelRef = useRef(null);

  const canManage = isGlobalAdmin() || isPrincipal();
  const schoolId = selectedSchool || userData?.schoolId;
  const featureMeta = FEATURE_LABELS[feature] || {};

  useEffect(() => {
    function onOutside(e) {
      if (panelRef.current && !panelRef.current.contains(e.target)) onClose();
    }
    document.addEventListener('mousedown', onOutside);
    return () => document.removeEventListener('mousedown', onOutside);
  }, [onClose]);

  const loadStaff = useCallback(async () => {
    try {
      const q1 = query(collection(db, 'users'), where('schoolIds', 'array-contains', schoolId));
      const q2 = query(collection(db, 'users'), where('schoolId', '==', schoolId));
      const [s1, s2] = await Promise.all([getDocs(q1), getDocs(q2)]);
      const map = new Map();
      s1.docs.forEach(d => map.set(d.id, { id: d.id, ...d.data() }));
      s2.docs.forEach(d => { if (!map.has(d.id)) map.set(d.id, { id: d.id, ...d.data() }); });
      const all = Array.from(map.values()).filter(u =>
        u.role !== 'global_admin' && !u.pendingSchools?.includes(schoolId)
      );
      setStaff(all);
    } catch (err) {
      console.error('PagePermissionsPanel load error:');
    }
  }, [schoolId]);

  useEffect(() => {
    if (!schoolId) return;
    loadStaff();
  }, [schoolId, loadStaff]);

  async function setAccessLevel(user, level) {
    const viewKey = featureMeta.view;
    const editKey = featureMeta.edit;
    const operationKey = `${user.id}_${level}`;
    setSaving(operationKey);
    setPanelError('');
    if (!isAppCheckConfigured) {
      setPanelError('App Check אינו מוגדר בגרסה שפורסמה, ולכן השרת חוסם שינוי הרשאות. יש להגדיר VITE_FIREBASE_APPCHECK_SITE_KEY ולפרסם את הממשק מחדש.');
      setSaving(null);
      return;
    }
    try {
      const patch = {
        ...(viewKey ? { [viewKey]: true } : {}),
        ...(featureMeta.viewAlias ? { [featureMeta.viewAlias]: true } : {}),
        ...(editKey ? { [editKey]: level === 'edit' } : {}),
        ...(featureMeta.editAlias ? { [featureMeta.editAlias]: level === 'edit' } : {}),
        ...Object.fromEntries((featureMeta.editExtra || []).map(key => [key, level === 'edit'])),
      };
      await updateStaffUser({ userId: user.id, schoolId, permissions: patch });
      setStaff(prev => prev.map(u => u.id === user.id
        ? { ...u, permissions: { ...(u.permissions || {}), ...patch } }
        : u
      ));
      setSaved(operationKey);
      setTimeout(() => setSaved(null), 1200);
    } catch (err) {
      const reason = callableReason(err);
      setPanelError(reason === 'not-found'
        ? 'שירות שמירת ההרשאות טרם נפרס. יש לפרוס את Cloud Functions לפני שינוי הרשאות.'
        : reason === 'failed-precondition' || reason === 'app-check-failed' || reason === 'unauthenticated'
          ? 'אימות האפליקציה נכשל. יש לוודא ש-App Check מוגדר בגרסה שפורסמה.'
          : reason === 'permission-denied'
            ? 'אין הרשאה לשנות את המשתמש הזה.'
            : 'שמירת ההרשאה נכשלה. השינוי לא נשמר.');
    }
    setSaving(null);
  }

  function getEffectivePerm(user, permKey) {
    if (!permKey) return true;
    if (['principal', 'institution_manager', 'global_admin', 'platform_admin'].includes(user.role)) return true;
    const aliasKey = permKey === featureMeta.view ? featureMeta.viewAlias : featureMeta.editAlias;
    const override = user.permissions?.[aliasKey] ?? user.permissions?.[permKey];
    if (override !== undefined) return override;
    const rolePermissions = user.rolePermissionsBySchool?.[schoolId] || {};
    const roleValue = rolePermissions?.[aliasKey] ?? rolePermissions?.[permKey];
    if (roleValue !== undefined) return roleValue;
    // Student data is sensitive and therefore has no implicit viewer access.
    if (permKey === 'students_view' || permKey === 'classes_view') return false;
    return permKey.endsWith('_view') || permKey === 'messages_send';
  }

  const filtered = staff.filter(u => {
    if (!search) return true;
    return (u.fullName || '').toLowerCase().includes(search.toLowerCase()) ||
           (u.email || '').toLowerCase().includes(search.toLowerCase());
  });

  if (!canManage) return null;

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9998,
      background: 'rgba(0,0,0,0.25)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      <div ref={panelRef} style={{
        background: '#fff', borderRadius: 14,
        boxShadow: '0 8px 40px rgba(0,0,0,0.18)',
        width: 560, maxHeight: '80vh',
        display: 'flex', flexDirection: 'column',
        direction: 'rtl', overflow: 'hidden',
      }}>
        {/* Header */}
        <div style={{
          padding: '1rem 1.25rem', borderBottom: '1px solid #f9f1ef',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Shield size={18} color="#fc5029" />
            <span style={{ fontWeight: 700, fontSize: '1rem' }}>
              הרשאות — {featureMeta.label}
            </span>
          </div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 4, borderRadius: 6, color: '#765968' }}>
            <X size={18} />
          </button>
        </div>

        {/* Legend */}
        <div style={{
          padding: '0.5rem 1.25rem', background: '#fbf6f5',
          borderBottom: '1px solid #f9f1ef',
          display: 'flex', gap: '1.5rem', fontSize: '0.78rem', color: '#765968',
        }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            <Eye size={13} color="#765968" /> צפייה
          </span>
          <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            <Edit3 size={13} color="#765968" /> עריכה
          </span>
          <span style={{ fontSize: '0.72rem', color: '#9b8790', marginRight: 'auto' }}>
            מנהל מוסד — גישה מלאה תמיד
          </span>
        </div>

        {/* Search */}
        <div style={{ padding: '0.75rem 1.25rem', borderBottom: '1px solid #f9f1ef' }}>
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="חיפוש לפי שם..."
            style={{
              width: '100%', padding: '0.45rem 0.75rem',
              border: '1px solid #eadfe2', borderRadius: 8,
              fontSize: '0.85rem', outline: 'none', boxSizing: 'border-box',
            }}
          />
          {panelError && <div role="alert" style={{ marginTop: '0.55rem', color: '#b91c1c', fontSize: '0.78rem', lineHeight: 1.5 }}>{panelError}</div>}
        </div>

        {/* User list */}
        <div style={{ overflowY: 'auto', flex: 1 }}>
          {filtered.length === 0 && (
            <div style={{ padding: '2rem', textAlign: 'center', color: '#9b8790', fontSize: '0.88rem' }}>
              לא נמצאו משתמשים
            </div>
          )}
          {filtered.map(user => {
            const isPrinc = ['principal', 'institution_manager', 'global_admin', 'platform_admin'].includes(user.role);
            const viewKey = featureMeta.view;
            const editKey = featureMeta.edit;
            const canView = getEffectivePerm(user, viewKey);
            const canEdit = getEffectivePerm(user, editKey);

            return (
              <div key={user.id} style={{
                padding: '0.65rem 1.25rem',
                borderBottom: '1px solid #fbf6f5',
                display: 'flex', alignItems: 'center', gap: '0.75rem',
              }}>
                {/* Avatar */}
                <div style={{
                  width: 34, height: 34, borderRadius: '50%',
                  background: isPrinc ? '#f9dab9' : '#f9f1ef',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '0.85rem', fontWeight: 700, color: isPrinc ? '#870335' : '#5f3b49',
                  flexShrink: 0,
                }}>
                  {user.fullName?.charAt(0) || '?'}
                </div>

                {/* Name + role */}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 600, fontSize: '0.88rem', color: '#1e000c', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                    {user.fullName}
                  </div>
                  <div style={{ fontSize: '0.72rem', color: '#9b8790' }}>
                    {user.jobTitle || ROLE_LABELS[user.role] || 'צופה'}
                  </div>
                </div>

                {/* Permission toggles */}
                <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
                  {viewKey && (
                    <PermToggle
                      label="צפייה"
                      icon={<Eye size={13} />}
                      active={isPrinc || (canView && !canEdit)}
                      disabled={isPrinc}
                      loading={saving === `${user.id}_view`}
                      justSaved={saved === `${user.id}_view`}
                      onChange={() => !isPrinc && setAccessLevel(user, 'view')}
                    />
                  )}
                  {editKey && (
                    <PermToggle
                      label="עריכה"
                      icon={<Edit3 size={13} />}
                      active={isPrinc || canEdit}
                      disabled={isPrinc}
                      loading={saving === `${user.id}_edit`}
                      justSaved={saved === `${user.id}_edit`}
                      onChange={() => !isPrinc && setAccessLevel(user, 'edit')}
                    />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div style={{
          padding: '0.75rem 1.25rem', borderTop: '1px solid #f9f1ef',
          background: '#fbf6f5', fontSize: '0.76rem', color: '#9b8790', textAlign: 'center',
        }}>
          בחירה ב״עריכה״ כוללת גם הרשאת צפייה. השינוי נשמר בשרת ומתעדכן אצל המשתמש לאחר רענון.
        </div>
      </div>
    </div>
  );
}

function PermToggle({ label, icon, active, disabled, loading, justSaved, onChange }) {
  return (
    <button
      onClick={onChange}
      disabled={disabled || loading}
      title={label}
      style={{
        display: 'flex', alignItems: 'center', gap: 4,
        padding: '0.3rem 0.6rem', borderRadius: 6, border: 'none',
        cursor: disabled ? 'default' : 'pointer',
        fontSize: '0.75rem', fontWeight: 600,
        background: active ? (justSaved ? '#dcfce7' : '#fbf6f5') : '#f9f1ef',
        color: active ? (justSaved ? '#16a34a' : '#870335') : '#9b8790',
        transition: 'all 0.15s',
        opacity: loading ? 0.6 : 1,
        minWidth: 60,
      }}
    >
      {justSaved ? <Check size={13} /> : icon}
      {label}
    </button>
  );
}

src/components/Shared/PermissionsMenu.js:
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { collection, getDocs, query, where } from 'firebase/firestore';
import { Ban, Edit3, Eye, MessageSquare, Settings2, Shield, Users, X } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { db } from '../../firebase';
import { usePermissions } from '../../hooks/usePermissions';
import { removeResourceAcl, upsertResourceAcl } from '../../services/adminUserService';
import './PermissionsMenu.css';

const ACCESS_TABS = Object.freeze([
  { id: 'view', label: 'צפייה', Icon: Eye }, { id: 'comment', label: 'תגובה', Icon: MessageSquare },
  { id: 'edit', label: 'עריכה', Icon: Edit3 }, { id: 'manage', label: 'ניהול ושיתוף', Icon: Settings2 },
  { id: 'deny', label: 'חסימה', Icon: Ban },
]);

function entryKey(principalType, principalId) { return `${principalType}:${principalId}`; }
function optionalSnapshot(promise) { return promise.catch(() => ({ docs: [] })); }

export default function PermissionsMenu({ resourceType, resourceId, resourceName, schoolId, onClose, position }) {
  const { isGlobalAdmin, isPrincipal } = useAuth();
  const { permissions } = usePermissions();
  const [staff, setStaff] = useState([]);
  const [teams, setTeams] = useState([]);
  const [roles, setRoles] = useState([]);
  const [classes, setClasses] = useState([]);
  const [existing, setExisting] = useState([]);
  const [entries, setEntries] = useState({});
  const [tab, setTab] = useState('view');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const menuRef = useRef(null);
  const requiredCapability = resourceType === 'task'
    ? 'tasks.managePermissions'
    : 'files.managePermissions';
  const canManage = isGlobalAdmin() || isPrincipal() || permissions[requiredCapability] === true;

  useEffect(() => {
    function outside(event) { if (menuRef.current && !menuRef.current.contains(event.target)) onClose(); }
    document.addEventListener('mousedown', outside);
    return () => document.removeEventListener('mousedown', outside);
  }, [onClose]);

  const load = useCallback(async () => {
    setLoading(true); setError('');
    try {
      const [primary, memberships, teamSnapshot, roleSnapshot, nestedRoleSnapshot, classSnapshot, nestedClassSnapshot, aclSnapshot] = await Promise.all([
        getDocs(query(collection(db, 'users'), where('schoolId', '==', schoolId))),
        getDocs(query(collection(db, 'users'), where('schoolIds', 'array-contains', schoolId))),
        optionalSnapshot(getDocs(collection(db, `teams_${schoolId}`))),
        optionalSnapshot(getDocs(collection(db, `roles_${schoolId}`))),
        optionalSnapshot(getDocs(collection(db, 'schools', schoolId, 'roleDefinitions'))),
        optionalSnapshot(getDocs(collection(db, `classes_${schoolId}`))),
        optionalSnapshot(getDocs(collection(db, 'schools', schoolId, 'classes'))),
        getDocs(query(
          collection(db, 'schools', schoolId, 'resourceAcls'),
          where('resourceType', '==', resourceType), where('resourceId', '==', resourceId),
        )),
      ]);
      const users = new Map();
      [...primary.docs, ...memberships.docs].forEach(item => users.set(item.id, { id: item.id, ...item.data() }));
      setStaff([...users.values()].filter(user => user.accountStatus !== 'disabled'));
      setTeams(teamSnapshot.docs.map(item => ({ id: item.id, ...item.data() })));
      const roleItems = new Map();
      [...roleSnapshot.docs, ...nestedRoleSnapshot.docs].forEach(item => roleItems.set(item.id, /** @type {any} */ ({ id: item.id, ...item.data() })));
      setRoles([...roleItems.values()].filter(role => role.status !== 'archived'));
      const classItems = new Map();
      [...classSnapshot.docs, ...nestedClassSnapshot.docs].forEach(item => classItems.set(item.id, { id: item.id, ...item.data() }));
      setClasses([...classItems.values()].filter(item => item.status !== 'archived'));
      const aclItems = aclSnapshot.docs.map(item => /** @type {any} */ ({ id: item.id, ...item.data() })).filter(item => item.active !== false);
      setExisting(aclItems);
      setEntries(Object.fromEntries(aclItems.map(item => [entryKey(item.principalType, item.principalId), {
        aclId: item.id,
        principalType: item.principalType,
        principalId: item.principalId,
        accessLevel: item.accessLevel,
        explicitDeny: item.explicitDeny === true,
        inherit: item.inherit !== false,
      }])));
    } catch { setError('לא ניתן לטעון את הרשאות המשאב.'); }
    finally { setLoading(false); }
  }, [resourceId, resourceType, schoolId]);

  useEffect(() => { load(); }, [load]);

  function toggle(principalType, principalId) {
    const key = entryKey(principalType, principalId);
    setEntries(previous => {
      const current = previous[key];
      const requested = { accessLevel: tab === 'deny' ? 'view' : tab, explicitDeny: tab === 'deny' };
      if (current && current.accessLevel === requested.accessLevel && current.explicitDeny === requested.explicitDeny) {
        const next = { ...previous }; delete next[key]; return next;
      }
      return { ...previous, [key]: { ...current, principalType, principalId, ...requested, inherit: true } };
    });
  }

  function selected(principalType, principalId) {
    const current = entries[entryKey(principalType, principalId)];
    return Boolean(current && (tab === 'deny' ? current.explicitDeny : !current.explicitDeny && current.accessLevel === tab));
  }

  async function save() {
    setSaving(true); setError('');
    try {
      const nextEntries = Object.values(entries);
      const removed = existing.filter(item => !entries[entryKey(item.principalType, item.principalId)]);
      await Promise.all([
        ...removed.map(item => removeResourceAcl({ schoolId, aclId: item.id })),
        ...nextEntries.map(item => upsertResourceAcl({
          schoolId,
          aclId: item.aclId,
          resourceType,
          resourceId,
          principalType: item.principalType,
          principalId: item.principalId,
          accessLevel: item.accessLevel,
          explicitDeny: item.explicitDeny,
          inherit: item.inherit,
          expiresAt: null,
        })),
      ]);
      onClose();
    } catch { setError('שמירת ההרשאות נדחתה. ודאו שיש לכם הרשאת ניהול ושכל המשתמשים שייכים למוסד.'); }
    finally { setSaving(false); }
  }

  const people = useMemo(() => staff.filter(user => {
    const value = `${user.fullName || ''} ${user.email || ''}`.toLowerCase();
    return !search || value.includes(search.toLowerCase());
  }), [search, staff]);
  if (!canManage) return null;

  return <div ref={menuRef} className="resource-acl-menu" style={position ? { position: 'fixed', top: position.y, left: position.x } : undefined}>
    <header><div><Shield size={15} /><strong>הרשאות — {resourceName}</strong><small>{resourceType === 'file' ? 'קובץ' : resourceType === 'folder' ? 'תיקייה' : 'משאב'}</small></div><button onClick={onClose} aria-label="סגירה"><X size={16} /></button></header>
    <div className="resource-acl-warning">לאחר הוספת הרשאה ראשונה, ברירת המחדל למשאב היא חסימה. חסימה מפורשת קודמת להרשאות אחרות.</div>
    <div className="resource-acl-tabs" role="tablist">{ACCESS_TABS.map(({ id, label, Icon }) => <button key={id} role="tab" aria-selected={tab === id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}><Icon size={13} /> {label}</button>)}</div>
    {error && <div className="resource-acl-error" role="alert">{error}</div>}
    <input className="resource-acl-search" value={search} onChange={event => setSearch(event.target.value)} placeholder="חיפוש איש צוות" aria-label="חיפוש איש צוות" />
    <div className="resource-acl-content">{loading ? <p>טוען…</p> : <>
      <section><h4><Users size={13} /> אנשי צוות</h4>{people.map(user => <label key={user.id}><input type="checkbox" checked={selected('user', user.id)} onChange={() => toggle('user', user.id)} /><span>{user.fullName || user.email}</span></label>)}</section>
      {teams.length > 0 && <section><h4>צוותים</h4>{teams.map(team => <label key={team.id}><input type="checkbox" checked={selected('team', team.id)} onChange={() => toggle('team', team.id)} /><span>{team.name}</span></label>)}</section>}
      {roles.length > 0 && <section><h4>תפקידים</h4>{roles.map(role => <label key={role.id}><input type="checkbox" checked={selected('role', role.id)} onChange={() => toggle('role', role.id)} /><span>{role.name}</span></label>)}</section>}
      {classes.length > 0 && <section><h4>כיתות</h4>{classes.map(item => <label key={item.id}><input type="checkbox" checked={selected('class', item.id)} onChange={() => toggle('class', item.id)} /><span>{item.name}</span></label>)}</section>}
    </>}</div>
    <footer><button className="btn btn-primary btn-sm" disabled={saving || loading} onClick={save}>{saving ? 'שומר…' : 'שמירת הרשאות'}</button><button className="btn btn-secondary btn-sm" onClick={onClose}>ביטול</button></footer>
  </div>;
}

