              value={viewMode}
              onChange={setViewMode}
              label="אופן הצגת אנשי הצוות"
              size="small"
              options={[
                { value: 'table', label: 'טבלה', icon: Table2 },
                { value: 'grid', label: 'כרטיסיות', icon: LayoutGrid },
              ]}
            />
            {canEdit && (
              <>
                <button className="btn btn-primary" onClick={() => setShowAddModal(true)}>
                  <UserPlus size={16} />
