                </button>
                <button className="btn btn-primary" onClick={openBulkModal} style={{ background: '#059669' }}>
                  <Users size={16} />
                  הוספה מרובה
                </button>
                <button className="btn btn-secondary" onClick={() => setShowRolesManager(true)}>
                  <Shield size={16} />
