                        <div className="td-user">
                          <div className="td-avatar">{user.fullName?.charAt(0)}</div>
                          {user.fullName}
                        </div>
                      </td>
                      <td>{schoolJobTitle(user, schoolId) || '—'}</td>
                      <td dir="ltr">{user.email}</td>
                      <td>
                        <div className="td-actions" style={{ display: 'flex', gap: '0.5rem' }}>
