                          <button className="btn btn-secondary btn-sm" onClick={() => handleReject(user.id)} style={{ display: 'flex', alignItems: 'center', gap: '0.25rem', color: '#ef4444' }}>
                            <XCircle size={14} /> דחייה
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
