                    </div>
                  )}

                  {/* Custom Roles */}
                  {customRoles.length > 0 && (
                    <div className="form-group">
                      <label>
                        <Shield size={14} style={{ display: 'inline', verticalAlign: 'middle', marginLeft: '0.3rem' }} />
