                            <input
                              type="checkbox"
                              checked={editForm.teamIds.includes(team.id)}
                              onChange={() => setEditForm(prev => ({
                                ...prev,
                                teamIds: prev.teamIds.includes(team.id)
                                  ? prev.teamIds.filter(id => id !== team.id)
                                  : [...prev.teamIds, team.id]
